export function getDamienTsarantosFragment(
  route: DamienTsarantosRoute,
  assetBase: string,
) {
  const base = assetBase.replace(/\/$/, "");
  return (FRAGMENTS[route] ?? FRAGMENTS["/"]).replaceAll(
    "__ASSET_BASE__",
    base,
  );
}
